def box(g,c):
    pts=[(r,cl) for r,row in enumerate(g) for cl,x in enumerate(row) if x==c]
    rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
    return min(rs),max(rs),min(cs),max(cs)
def interior(g,c):
    r0,r1,c0,c1=box(g,c)
    return [[1 if g[r][cl]==c else 0 for cl in range(c0+1,c1)] for r in range(r0+1,r1)]
